 const n=await figma.getNodeByIdAsync(id);
 if(!n){out[id]='MISSING';continue;}
 const walk=(nd,d)=>{let s=nd.type+' "'+nd.name+'" '+Math.round(nd.width)+'x'+Math.round(nd.height);
  if(nd.type==='FRAME'||nd.type==='COMPONENT'){s+=' layout='+(nd.layoutMode||'NONE')+' prim='+(nd.primaryAxisSizingMode||'')+' counter='+(nd.counterAxisSizingMode||'')+' clips='+nd.clipsContent;}
  if(nd.type==='TEXT'){s+=' ['+nd.characters.slice(0,20)+']';}
  if(d<2&&nd.children&&nd.children.length)s+=' {'+nd.children.map(c=>walk(c,d+1)).join(' | ')+'}';
  return s;};
 out[id]=walk(n,0);
}
return JSON.stringify(out,null,1);

